// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 callCount) public {
        vm.assume(callCount >= 1 && callCount <= 10);
        uint expectedPot = 0;
        for (uint i = 0; i < callCount; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            expectedPot += 10;
        }
        assertTrue(c.pot() == expectedPot);
    }
}
